import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Icon } from "@/components/ui/icon"
import { IndexCard, IndexCardContent, IndexCardFooter, IndexCardHeader, IndexCardTitle } from "@/components/ui/index-card"
import { PRONOUNS, TIME_ZONES, type ProfileValues } from "@/components/blocks/settings-profile/components/settings-profile-schema"

export function SettingsProfileCard({ values, photo }: { values: ProfileValues; photo?: string }) {
  const name = values.name.trim() || "Your name"
  const pronouns = PRONOUNS.find((p) => p.value === values.pronouns)
  const zone = TIME_ZONES.find((z) => z.value === values.timezone)
  return (
    <IndexCard hole flag="grape" seed="profile-card" tilt={-0.2} aria-label="Preview of your profile card" role="group" className="min-h-[254px] max-w-none">
      <IndexCardHeader>
        <IndexCardTitle>{name}</IndexCardTitle>
        <Avatar size="sm" ring="none">
          {photo ? <AvatarImage src={photo} alt="" /> : null}
          <AvatarFallback name={name} />
        </Avatar>
      </IndexCardHeader>
      <IndexCardContent className="text-[15px]">
        <p className="ll-num text-muted-foreground">
          @{values.username.trim() || "username"}
          {pronouns && pronouns.value !== "none" ? ` · ${pronouns.label}` : ""}
        </p>
        <p className="line-clamp-3 wrap-break-word">{values.bio.trim() || "A line or two about you goes here."}</p>
      </IndexCardContent>
      <IndexCardFooter className="flex-wrap content-start justify-start gap-x-4">
        {values.website ? (
          <span className="inline-flex h-[30px] max-w-full min-w-0 items-center gap-1.5">
            <Icon name="link" size={14} className="shrink-0" />
            <span className="truncate">{values.website.replace(/^https?:\/\//, "")}</span>
          </span>
        ) : null}
        {zone ? (
          <span className="inline-flex h-[30px] items-center gap-1.5">
            <Icon name="globe" size={14} className="shrink-0" />
            {zone.label}
          </span>
        ) : null}
        {!values.discoverable ? <span className="h-[30px] text-ink-soft">not in search</span> : null}
      </IndexCardFooter>
    </IndexCard>
  )
}

"use client"

import * as React from "react"

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"

const MAX_BYTES = 2 * 1024 * 1024

export function SettingsProfilePhoto({ name, photo, onPhoto }: { name: string; photo?: string; onPhoto: (url: string | undefined) => void }) {
  const input = React.useRef<HTMLInputElement>(null)
  const [error, setError] = React.useState("")
  const help = React.useId()

  const onFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    e.target.value = ""
    if (!file) return
    if (!file.type.startsWith("image/")) return setError("Choose an image: JPG, PNG or GIF.")
    if (file.size > MAX_BYTES) return setError("That picture is over 2 MB. Try a smaller one.")
    setError("")
    onPhoto(URL.createObjectURL(file))
  }

  return (
    <div className="flex items-center gap-5">
      <Avatar size="xl" seed="profile-photo" className="data-[size=xl]:size-20">
        {photo ? <AvatarImage src={photo} alt="" /> : null}
        <AvatarFallback name={name || "You"} className="group-data-[size=xl]/avatar:text-3xl" />
      </Avatar>
      <div className="grid gap-2">
        <p className="text-[15px] font-bold">Photo</p>
        <div className="flex flex-wrap gap-2">
          <Button type="button" variant="outline" size="sm" onClick={() => input.current?.click()}>
            {photo ? "Choose another" : "Upload a photo"}
          </Button>
          {photo ? (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={() => {
                setError("")
                onPhoto(undefined)
              }}
            >
              Remove
            </Button>
          ) : null}
        </div>
        <p id={help} className="text-sm text-muted-foreground">
          JPG, PNG or GIF, up to 2 MB. Without one you get your initials.
        </p>
        {error ? (
          <p role="alert" className="text-sm font-bold text-red">
            {error}
          </p>
        ) : null}
        <input ref={input} type="file" accept="image/*" hidden onChange={onFile} aria-describedby={help} />
      </div>
    </div>
  )
}
